import { useMemo, useState } from 'react'
import { AlertTriangle, BrainCircuit, CheckCircle2, ChevronRight, Crosshair, ShieldAlert, ShieldCheck } from 'lucide-react'

export type TriageItem = { nodeId: string; label: string; kind: string; priority: number; urgency: 'critical' | 'high' | 'medium' | 'low'; risk: number; confidence: number; conflicts: number; connectivity: number; evidenceStrength: number; recommendedAction: string; investigationBrief: string; executiveImpact: string }
export type TriagePayload = { priorities: TriageItem[]; metrics: { riskExposure: number; executivePriority: number; conflictedNodes: number; evidenceBackedNodes: number; triagedNodes: number }; topPriority?: TriageItem | null }

const urgencyIcon = { critical: ShieldAlert, high: AlertTriangle, medium: Crosshair, low: CheckCircle2 }

export function AutonomousTriagePanel({ triage, onInvestigate }: { triage: TriagePayload; onInvestigate?: (item: TriageItem) => void }) {
  const [selectedId, setSelectedId] = useState(triage.topPriority?.nodeId ?? triage.priorities[0]?.nodeId ?? null)
  const selected = useMemo(() => triage.priorities.find((item) => item.nodeId === selectedId) ?? triage.topPriority ?? triage.priorities[0], [selectedId, triage])
  return <section className="overflow-hidden rounded-2xl border bg-card"><header className="flex flex-wrap items-center justify-between gap-3 border-b px-5 py-4"><div><div className="flex items-center gap-2 font-semibold"><BrainCircuit className="h-4 w-4 text-primary" /> Autonomous Security Triage</div><p className="mt-1 text-xs text-muted-foreground">Decision support derived from graph risk, evidence strength, connectivity, and conflict signals.</p></div><span className="rounded-full border px-2.5 py-1 text-[10px] font-bold uppercase">{triage.metrics.triagedNodes} triaged</span></header><div className="grid gap-px border-b bg-border sm:grid-cols-2 lg:grid-cols-4"><Metric label="Risk exposure" value={`${triage.metrics.riskExposure}/100`} /><Metric label="Executive priority" value={`${triage.metrics.executivePriority}/100`} /><Metric label="Conflicted nodes" value={triage.metrics.conflictedNodes} /><Metric label="Evidence-backed" value={triage.metrics.evidenceBackedNodes} /></div><div className="grid lg:grid-cols-[minmax(0,1fr)_410px]"><div className="divide-y">{triage.priorities.slice(0, 10).map((item, index) => { const Icon = urgencyIcon[item.urgency]; return <button key={item.nodeId} type="button" onClick={() => setSelectedId(item.nodeId)} className={`flex w-full items-center gap-3 px-5 py-3 text-left transition hover:bg-muted/30 ${item.nodeId === selectedId ? 'bg-primary/5' : ''}`} aria-pressed={item.nodeId === selectedId}><span className="grid h-8 w-8 shrink-0 place-items-center rounded-lg border bg-background text-[10px] font-black">#{index + 1}</span><div className="min-w-0 flex-1"><div className="truncate text-xs font-semibold">{item.label}</div><div className="mt-1 flex flex-wrap gap-2 text-[9px] text-muted-foreground"><span>{item.kind}</span><span>Risk {item.risk}</span><span>Confidence {item.confidence}</span>{item.conflicts > 0 && <span className="text-amber-600">{item.conflicts} conflict{item.conflicts > 1 ? 's' : ''}</span>}</div></div><Icon className="h-4 w-4 shrink-0" /></button> })}</div><aside className="border-t bg-muted/10 p-5 lg:border-l lg:border-t-0">{selected ? <><div className="text-[10px] font-semibold uppercase tracking-[0.14em] text-muted-foreground">Investigation brief</div><h3 className="mt-2 text-lg font-bold">{selected.label}</h3><p className="mt-2 text-xs leading-5 text-muted-foreground">{selected.investigationBrief}</p><div className="mt-4 grid grid-cols-2 gap-2"><Metric label="Priority" value={selected.priority} /><Metric label="Risk" value={selected.risk} /><Metric label="Confidence" value={selected.confidence} /><Metric label="Evidence" value={selected.evidenceStrength} /></div><div className="mt-4 rounded-xl border bg-background p-3"><div className="text-[10px] font-semibold uppercase tracking-wider">Recommended action</div><p className="mt-1 text-[11px] leading-5 text-muted-foreground">{selected.recommendedAction}</p></div><div className="mt-3 rounded-xl border border-primary/20 bg-primary/5 p-3"><div className="text-[10px] font-semibold uppercase tracking-wider">Executive impact</div><p className="mt-1 text-[11px] leading-5 text-muted-foreground">{selected.executiveImpact}</p></div>{onInvestigate && <button type="button" onClick={() => onInvestigate(selected)} className="mt-4 flex w-full items-center justify-center gap-2 rounded-xl bg-primary px-3 py-2.5 text-xs font-semibold text-primary-foreground"><ShieldCheck className="h-3.5 w-3.5" /> Open investigation <ChevronRight className="h-3.5 w-3.5" /></button>}</> : <div className="grid min-h-[240px] place-items-center text-xs text-muted-foreground">No triage signal is available.</div>}</aside></div></section>
}
function Metric({ label, value }: { label: string; value: string | number }) { return <div className="bg-card p-3"><div className="text-[9px] uppercase tracking-wider text-muted-foreground">{label}</div><div className="mt-1 text-lg font-black">{value}</div></div> }
